368	          /* My Jobs view — full management */
369	          <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
370	            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
