153	  const intervals: { start: number; end: number }[] = [];
154	  const currentYear = new Date().getFullYear();
155	  const currentMonth = new Date().getMonth() + 1;
156	
157	  for (const role of rolesWithDates) {
158	    const startRaw = role.start || role.start_date || role.from || "";
159	    const endRaw = role.end || role.end_date || role.to || "";
160	
161	    const startDate = parseDate(String(startRaw), currentYear, currentMonth);
162	    let endDate = parseDate(String(endRaw), currentYear, currentMonth);
163	
164	    // Handle "present", "current", "ongoing" etc.
165	    const endLower = String(endRaw).toLowerCase().trim();
166	    if (!endRaw || endLower === "present" || endLower === "current" || endLower === "ongoing" || endLower === "now" || endLower === "till date" || endLower === "till now") {
167	      endDate = currentYear + (currentMonth - 1) / 12;
168	    }
169	
170	    if (startDate > 0 && endDate > 0 && endDate >= startDate) {
171	      intervals.push({ start: startDate, end: endDate });
172	    }
173	  }
