206	
207	  // "Jan 2020", "January 2020"
208	  const monthYear = s.match(/^([a-zA-Z]+)\s+(\d{4})/);
209	  if (monthYear) {
210	    const month = monthNameToNum(monthYear[1]);
211	    if (month > 0) return parseInt(monthYear[2]) + (month - 1) / 12;
212	  }
213	
214	  // Plain year "2020"
215	  const plainYear = s.match(/^(\d{4})$/);
216	  if (plainYear) return parseInt(plainYear[1]);
217	
218	  return 0;
219	}
