221	function monthNameToNum(name: string): number {
222	  const months: Record<string, number> = {
223	    jan: 1, january: 1, feb: 2, february: 2, mar: 3, march: 3,
224	    apr: 4, april: 4, may: 5, jun: 6, june: 6,
225	    jul: 7, july: 7, aug: 8, august: 8, sep: 9, september: 9,
226	    oct: 10, october: 10, nov: 11, november: 11, dec: 12, december: 12,
227	  };
228	  return months[name.toLowerCase().trim()] || 0;
229	}
