231	function extractRequiredYears(experienceReq: string): number {
232	  if (!experienceReq) return 0;
233	  const match = experienceReq.match(/(\d+)\+?\s*(?:years?|yrs?)/i);
234	  return match ? parseInt(match[1]) : 0;
235	}
236	
237	function scoreExperienceBand(years: number, bands: ExperienceBand[]): number {
238	  for (const band of bands) {
239	    if (years >= band.min_years && years < band.max_years) return band.score;
240	  }
241	  // If beyond all bands, return max score
242	  return bands.length > 0 ? bands[bands.length - 1].score : 50;
243	}
244	
245	function scoreEducation(education: any[], levels: EducationLevel[]): { score: number; highestDegree: string } {
246	  if (!Array.isArray(education) || education.length === 0) {
247	    return { score: 0, highestDegree: "none" };
248	  }
249	
250	  let bestScore = 0;
251	  let bestLevel = "unknown";
252	
253	  for (const edu of education) {
254	    const degree = String(edu.degree || edu.qualification || edu.level || "").toLowerCase().trim();
255	    if (!degree) continue;
256	
257	    for (const level of levels) {
258	      for (const alias of level.aliases) {
259	        if (degree.includes(alias.toLowerCase())) {
260	          if (level.score > bestScore) {
261	            bestScore = level.score;
262	            bestLevel = level.level;
263	          }
264	          break;
265	        }
266	      }
267	    }
268	  }
269	
270	  return { score: bestScore, highestDegree: bestLevel };
271	}
