273	function ruleBasedScoreResume(
274	  parsedJson: any,
275	  jdAnalysis: any,
276	  cfg: {
277	    experience_bands: ExperienceBand[];
278	    education_levels: EducationLevel[];
279	    rule_dimension_weights: Record<string, number>;
280	    must_have_penalty_per_missing: number;
281	    hard_fit_cap: number;
282	    algorithm_version: number;
283	  },
284	) {
285	  const p = parsedJson || {};
286	  const allResumeTerms = extractResumeTerms(parsedJson);
287	
288	  // ── Skill Match ──
289	  const jdSkills = [
290	    ...(jdAnalysis.critical_must_haves || []),
291	    ...(jdAnalysis.preferred_must_haves || []),
292	    ...(jdAnalysis.nice_to_have || []),
293	  ];
294	  const matchedSkills: string[] = [];
295	  const missingSkills: string[] = [];
296	  for (const skill of jdSkills) {
297	    if (fuzzyMatch(skill, allResumeTerms)) matchedSkills.push(skill);
298	    else missingSkills.push(skill);
299	  }
300	  const skillScore = jdSkills.length > 0 ? Math.round((matchedSkills.length / jdSkills.length) * 100) : 50;
301	
302	  // ── Tool Match ──
303	  const jdTools = jdAnalysis.tools || [];
304	  const matchedTools: string[] = [];
305	  const missingTools: string[] = [];
306	  for (const tool of jdTools) {
307	    if (fuzzyMatch(tool, allResumeTerms)) matchedTools.push(tool);
308	    else missingTools.push(tool);
309	  }
310	  const toolScore = jdTools.length > 0 ? Math.round((matchedTools.length / jdTools.length) * 100) : 50;
311	
312	  // ── Experience Fit ──
313	  const rolesWithDates = p.roles_with_dates || [];
314	  const totalYears = extractTotalYears(rolesWithDates);
315	  const requiredYears = extractRequiredYears(jdAnalysis.experience_requirements || "");
316	  let experienceScore = scoreExperienceBand(totalYears, cfg.experience_bands);
317	  if (requiredYears > 0 && totalYears >= requiredYears) {
318	    experienceScore = Math.min(100, experienceScore + 10);
319	  }
320	
321	  // ── Education Fit ──
322	  const education = p.education || [];
323	  const eduResult = scoreEducation(education, cfg.education_levels);
324	  const educationScore = eduResult.score;
325	
326	  // ── Must-Have Coverage ──
327	  const criticalMustHaves = jdAnalysis.critical_must_haves || [];
328	  const matchedMustHaves: string[] = [];
329	  const missingMustHaves: string[] = [];
330	  for (const mh of criticalMustHaves) {
331	    if (fuzzyMatch(mh, allResumeTerms)) matchedMustHaves.push(mh);
332	    else missingMustHaves.push(mh);
333	  }
334	  const mustHaveScore = criticalMustHaves.length > 0
335	    ? Math.round((matchedMustHaves.length / criticalMustHaves.length) * 100) : 100;
336	
337	  // ── Overall Score ──
338	  // Must-haves are handled via penalty only (not as a weighted dimension) to avoid double-counting
339	  const weights = cfg.rule_dimension_weights;
340	  const baseWeight = (weights.skill_match || 0.30) + (weights.experience_fit || 0.25) +
341	    (weights.tool_match || 0.20) + (weights.education_fit || 0.15);
342	  const normalizer = baseWeight > 0 ? 1 / baseWeight : 1; // re-normalize without must_have_coverage
343	  let overallScore =
344	    (skillScore * (weights.skill_match || 0.30) +
345	    experienceScore * (weights.experience_fit || 0.25) +
346	    toolScore * (weights.tool_match || 0.20) +
347	    educationScore * (weights.education_fit || 0.15)) * normalizer;
348	
349	  // Apply must-have penalty (only mechanism for must-have impact — no double-counting)
350	  overallScore -= missingMustHaves.length * cfg.must_have_penalty_per_missing;
351	  overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
352	
353	  // Hard fit check — proportional cap so partial fits rank higher than zero fits
354	  const hardFit = missingMustHaves.length === 0;
355	  if (!hardFit) {
356	    const proportionalCap = Math.max(20, cfg.hard_fit_cap - (missingMustHaves.length - 1) * 10);
357	    overallScore = Math.min(overallScore, proportionalCap);
358	  }
359	
360	  // ── Build strengths & gaps ──
361	  const dimensionScores = [
362	    { name: "Skill Match", score: skillScore },
363	    { name: "Experience", score: experienceScore },
364	    { name: "Tools", score: toolScore },
365	    { name: "Education", score: educationScore },
366	    { name: "Must-Haves", score: mustHaveScore },
367	  ];
368	  dimensionScores.sort((a, b) => b.score - a.score);
369	  const strengths = dimensionScores.filter(d => d.score >= 60).map(d => `${d.name}: ${d.score}%`);
370	  const gaps = dimensionScores.filter(d => d.score < 50).map(d => `${d.name}: ${d.score}%`);
371	
372	  // Add matched skills to strengths
373	  if (matchedMustHaves.length > 0) {
374	    strengths.push(`Matched must-haves: ${matchedMustHaves.join(", ")}`);
375	  }
376	  if (missingMustHaves.length > 0) {
377	    gaps.push(`Missing must-haves: ${missingMustHaves.join(", ")}`);
378	  }
379	
380	  return {
381	    scoring_version: `rule-v1-algo${cfg.algorithm_version}`,
382	    overall_score: overallScore,
383	    hard_fit: hardFit,
384	    // Confidence based on data completeness: skills found + experience parsed + education found
385	    confidence: Math.min(90, Math.round(
386	      (matchedSkills.length > 0 ? 30 : 0) +
387	      (totalYears > 0 ? 30 : 0) +
388	      (educationScore > 0 ? 20 : 0) +
389	      (matchedMustHaves.length > 0 ? 10 : 0)
390	    )),
391	    skill_score: skillScore,
392	    experience_score: experienceScore,
393	    education_score: educationScore,
394	    category_scores_json: {
395	      skill_match: { score: skillScore, matched: matchedSkills, missing: missingSkills },
396	      experience_fit: { score: experienceScore, years_found: totalYears, years_required: requiredYears },
397	      tool_match: { score: toolScore, matched: matchedTools, missing: missingTools },
398	      education_fit: { score: educationScore, highest_degree: eduResult.highestDegree },
399	      must_have_coverage: { score: mustHaveScore, matched: matchedMustHaves, missing: missingMustHaves },

400	    },
401	    matched_must_haves: matchedMustHaves,
402	    missing_must_haves: missingMustHaves,
403	    missing_skills: [...missingMustHaves, ...missingTools],
404	    strengths_json: strengths,
405	    gaps_json: gaps,
406	    interview_questions: [],
407	    explanation_json: {
408	      summary: `Rule-based scoring: ${matchedSkills.length}/${jdSkills.length} skills matched, ${totalYears} years experience (${requiredYears} required), ${eduResult.highestDegree} degree.`,
409	      scoring_mode: "rule_based",
410	      dimension_breakdown: {
411	        skill_match: skillScore,
412	        experience_fit: experienceScore,
413	        tool_match: toolScore,
414	        education_fit: educationScore,
415	        must_have_coverage: mustHaveScore,
416	      },
417	    },
418	  };
419	}
