544	    await logSystemError({ function_name: "rank-resumes", error_type: "PARSE_INVOKE", severity: "warning", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
545	  }
546	
547	  // Step 2: Re-fetch resume after parsing
548	  const { data: resume } = await supabase.from("resumes").select("*").eq("id", resumeId).single();
549	  if (!resume) {
550	    console.error(`Resume ${resumeId} not found after parsing`);
551	    return false;
552	  }
553	
554	  const rawText = resume.parsed_text || "";
555	  const parsedJson = resume.parsed_json;
556	
557	  // Step 3: Check if we have enough content to score
558	  const hasUsefulParsedJson = parsedJson && (
559	    (Array.isArray(parsedJson.skills_with_evidence) && parsedJson.skills_with_evidence.length > 0) ||
560	    (Array.isArray(parsedJson.roles_with_dates) && parsedJson.roles_with_dates.length > 0) ||
561	    (Array.isArray(parsedJson.education) && parsedJson.education.length > 0)
562	  );
563	  if (rawText.trim().length < 50 && !hasUsefulParsedJson) {
564	    console.warn(`Resume ${resumeId}: insufficient content after parsing, inserting zero score`);
565	    const summaryMsg = resume.status === "failed"
566	      ? "Could not extract text from this file. It may be image-based or have unsupported formatting. Please re-upload a text-based PDF or DOCX file."
567	      : "Resume content too short to evaluate. Please re-upload a valid PDF/DOCX.";
568	    const resultData = {
569	      resume_id: resumeId, job_id: jobId, scoring_version: "insufficient",
570	      overall_score: 0, hard_fit: false, confidence: 0,
571	      category_scores_json: {}, strengths_json: [], gaps_json: [],
572	      interview_questions: [], explanation_json: { extraction_failed: true },
573	      matched_must_haves: [], missing_must_haves: [], missing_skills: [],
574	      summary: summaryMsg,
575	      skill_score: null, experience_score: null, education_score: null,
576	    };
577	    const { data: existing } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
578	    if (existing) await supabase.from("results").update(resultData as any).eq("id", existing.id);
579	    else await supabase.from("results").insert(resultData as any);
580	    return false;
581	  }
582	
583	  // Step 4: Score — rule-based or GPT
584	  if (cfg.scoring_mode === "rule_based") {
585	    try {
586	      console.log(`Rule-based scoring for resume ${resumeId}...`);
587	      const ruleResult = ruleBasedScoreResume(parsedJson, jdAnalysis, cfg);
588	
589	      // Update candidate name from parsed data if available
590	      const parsedName = parsedJson?.candidate_name || parsedJson?.name;
591	      if (parsedName && parsedName !== "Unknown Candidate") {
592	        await supabase.from("resumes").update({ candidate_name: parsedName, status: "done" }).eq("id", resumeId);
593	      } else {
594	        await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
595	      }
596	
597	      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
598	      const resultData = { resume_id: resumeId, job_id: jobId, ...ruleResult };
599

600	      if (existingResult) {
601	        await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
602	      } else {
603	        await supabase.from("results").insert(resultData as any);
604	      }
605	      console.log(`Resume ${resumeId} rule-scored: overall=${ruleResult.overall_score}, hardFit=${ruleResult.hard_fit}`);
606	      return true;
607	    } catch (err) {
608	      console.error(`Rule-based scoring failed for ${resumeId}:`, err);
609	      await logSystemError({ function_name: "rank-resumes", error_type: "RULE_SCORING", severity: "error", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
610	      await supabase.from("resumes").update({ status: "failed" }).eq("id", resumeId);
611	      return false;
612	    }
613	  }
614	
615	  // Step 5: Deep score with OpenAI (GPT mode)
616	  try {
617	    const resumeText = rawText || JSON.stringify(parsedJson || {});
618	    const deepResult = await deepScoreResume(
619	      job.job_description, resumeText, parsedJson,
620	      jdAnalysis, dimensions, cfg, deepScoringPrompt
621	    );
622	
623	    let overallScore = 0;
624	    const categoryScores = deepResult.category_scores || {};
625	
626	    const normalizeKey = (k: string) => k.toLowerCase().replace(/[\s_-]+/g, "_").trim();
627	    const scoreKeyMap = new Map<string, any>();
628	    for (const [k, v] of Object.entries(categoryScores)) {
629	      scoreKeyMap.set(normalizeKey(k), v);
630	    }
631	
632	    // Compute weighted overall score from dimension scores
633	    let totalWeight = 0;
634	    for (const dim of dimensions) {
635	      const weight = dynamicWeights[dim.key] ?? 0;
636	      const scoreEntry = categoryScores[dim.key] || scoreKeyMap.get(normalizeKey(dim.key));
637	      overallScore += (scoreEntry?.score ?? 0) * weight;
638	      totalWeight += weight;
639	    }
640	
641	    // If weights don't sum to ~1.0 (dimension key mismatch), try matching all GPT-returned scores
642	    if (overallScore === 0 && Object.keys(categoryScores).length > 0 && totalWeight > 0) {
643	      // Dimension keys from GPT didn't match JD analysis keys — re-map by position
644	      const gptScores = Object.values(categoryScores).map((v: any) => v?.score ?? 0);
645	      const dimWeights = dimensions.map(d => dynamicWeights[d.key] ?? 0);
646	      if (gptScores.length > 0 && dimWeights.length > 0) {
647	        overallScore = 0;
648	        const count = Math.min(gptScores.length, dimWeights.length);
649	        for (let i = 0; i < count; i++) {
650	          overallScore += gptScores[i] * dimWeights[i];
651	        }
652	      }
653	    }
654	
655	    overallScore = Math.round(Math.max(0, Math.min(100, overallScore)) * 100) / 100;
656	
657	    // Retry if scoring looks unreliable: all zeros, very low confidence, or >50% dimensions at zero
658	    const scoreValues = Object.values(categoryScores).map((v: any) => v?.score ?? 0);
659	    const zeroCount = scoreValues.filter(s => s === 0).length;
660	    const allZero = scoreValues.length > 0 && scoreValues.every(s => s === 0);
661	    const mostlyZero = scoreValues.length > 0 && zeroCount > scoreValues.length / 2;
662	    const lowConfidence = (deepResult.confidence ?? 0) < 20;
663	    if ((allZero || (mostlyZero && lowConfidence)) && resumeText.length > 200) {
664	      console.warn(`Resume ${resumeId}: all scores=0, retrying once...`);
665	      try {
666	        const retryResult = await deepScoreResume(
667	          job.job_description, resumeText, parsedJson,
668	          jdAnalysis, dimensions, cfg, deepScoringPrompt
669	        );
670	        const retryScores = retryResult.category_scores || {};
671	        const retryAllZero = Object.values(retryScores).every((v: any) => (v?.score ?? 0) === 0);
672	        if (!retryAllZero) {
673	          Object.assign(deepResult, retryResult);
674	          Object.assign(categoryScores, retryScores);
675	          overallScore = 0;
676	          const retryKeyMap = new Map<string, any>();
677	          for (const [k, v] of Object.entries(retryScores)) retryKeyMap.set(normalizeKey(k), v);
678	          for (const dim of dimensions) {
679	            const weight = dynamicWeights[dim.key] ?? 0;
680	            const scoreEntry = retryScores[dim.key] || retryKeyMap.get(normalizeKey(dim.key));
681	            overallScore += (scoreEntry?.score ?? 0) * weight;
682	          }
683	          // If dimension keys didn't match, re-map by position (same as primary path)
684	          if (overallScore === 0 && Object.keys(retryScores).length > 0) {
685	            const gptScores = Object.values(retryScores).map((v: any) => v?.score ?? 0);
686	            const dimWeights = dimensions.map(d => dynamicWeights[d.key] ?? 0);
687	            const count = Math.min(gptScores.length, dimWeights.length);
