489	  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
490	    if (!user) return [];
491	    const resumeIds: string[] = [];
492	    const failures: string[] = [];
493	    const skippedDupes: string[] = [];
494	
495	    // Fetch existing filenames for this job to prevent DB-level duplicates
496	    const { data: existingInDb } = await supabase
497	      .from("resumes")
498	      .select("filename")
499	      .eq("job_id", jobId);
500	    const dbFilenames = new Set((existingInDb ?? []).map((r: any) => r.filename.toLowerCase()));
501	
502	    for (const { file, name } of filesToUpload) {
503	      // Skip if this filename already exists in the job
504	      if (dbFilenames.has(name.toLowerCase())) {
505	        skippedDupes.push(name);
506	        continue;
507	      }
508	      try {
509	        const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
510	        const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
511	        if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
512	        const { data: resume, error: resumeError } = await supabase
513	          .from("resumes")
514	          .insert({ job_id: jobId, filename: name, file_path: filePath })
515	          .select("id")
516	          .single();
517	        if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
